import type { ReactNode } from "react";
import { googleSansFlex } from "@/lib/fonts";
import { cx } from "./shared";
import styles from "./mdx.module.css";

/** Styling boundary only; heading IDs are generated by rehype-slug.
 * KnowledgeArticleScaffold owns H1, byline, ToC and sources in Uteguiden.
 * Other documents can use ArticleMeta, TableOfContents and References.
 */
export function MdxContent({ children }: { children?: ReactNode }) {
  return (
    <div className={cx(googleSansFlex.variable, styles.content)}>
      {children}
    </div>
  );
}
